meanings.gt_sql:
SELECT AVG(Salary) AS average_salary
FROM employee
GROUP BY Dno;

turns.sql:
SELECT AVG(e.Salary) AS avg_salary
FROM employee e
WHERE NOT EXISTS (
    SELECT 1 FROM project p
    WHERE p.Dnum = e.Dno
    AND NOT EXISTS (
        SELECT 1 FROM works_on w
        WHERE w.Essn = e.Ssn AND w.Pno = p.Pnumber
    )
);
